// PackagingScreen.js
import React from 'react';
import { FaUtensils, FaShoppingBag, FaShoppingCart } from 'react-icons/fa';

export default function PackagingScreen({ onNext, cart = [], onViewCart, onCheckout }) {
  const totalQty = cart.reduce((s, i) => s + (i.qty || 1), 0);
  const totalPrice = cart.reduce((s, i) => s + (i.total || i.price || 0), 0);

  return (
    <div className="packaging-screen">
      <h1 className="packaging-header">포장 선택</h1>
      <div className="packaging-divider" />

      <div className={`packaging-options ${cart.length > 0 ? 'with-cart' : ''}`}>
        <button className="packaging-option" onClick={() => onNext('eat-in')}>
          <FaUtensils size={48} />
          <span>매장식사</span>
        </button>

        <button className="packaging-option" onClick={() => onNext('take-out')}>
          <FaShoppingBag size={48} />
          <span>포장</span>
        </button>
      </div>

      {/* 장바구니가 있을 때만 하단 바 표시 */}
      {cart.length > 0 && (
        <footer className="checkout-bar">
          <button className="cart-link" onClick={onViewCart}>
            <FaShoppingCart size={18}/> 장바구니 보기
            {totalQty > 0 && <span className="badge">{totalQty}</span>}
          </button>
          <button className="btn-pay" onClick={onCheckout}>
            총 {totalQty}개 {totalPrice.toLocaleString()}원 결제하기
          </button>
        </footer>
      )}
    </div>
  );
}
